package http
import("net/http";"github.com/gin-gonic/gin";"eip-platform/backend/internal/auth";"eip-platform/backend/internal/domain";"eip-platform/backend/internal/repository")
func listRuns(c *gin.Context){items:=repository.Runs(c.Param("projectId"));c.JSON(200,gin.H{"items":items,"total":len(items)})}
func registerModel(c *gin.Context){var m domain.ModelVersion;if c.ShouldBindJSON(&m)!=nil||m.ExperimentRunID==""{Error(c,400,"BAD_INPUT","experiment run required",nil);return};m.ApprovalStatus="approved";v,e:=repository.RegisterModel(m);if e!=nil{Error(c,400,"BAD_INPUT",e.Error(),nil);return};repository.Audit(domain.AuditEvent{Actor:"api",ProjectID:c.Param("projectId"),ResourceType:"model",ResourceID:v.ID,Action:"register",RequestID:RequestID(c)});c.JSON(201,v)}
func listModels(c *gin.Context){items:=repository.Models();c.JSON(200,gin.H{"items":items,"total":len(items)})}
func createService(c *gin.Context){var s domain.OnlineService;if c.ShouldBindJSON(&s)!=nil||s.Name==""{Error(c,400,"BAD_INPUT","service name required",nil);return};s.ProjectID=c.Param("projectId");v,e:=repository.CreateService(s);if e!=nil{Error(c,422,"MODEL_NOT_PUBLISHED",e.Error(),nil);return};repository.Audit(domain.AuditEvent{Actor:"api",ProjectID:s.ProjectID,ResourceType:"service",ResourceID:v.ID,Action:"create",RequestID:RequestID(c)});c.JSON(http.StatusCreated,v)}
func listServices(c *gin.Context){items:=repository.Services(c.Param("projectId"));c.JSON(200,gin.H{"items":items,"total":len(items)})}
func registerDeliveryRoutes(g *gin.RouterGroup){g.GET("/experiment-runs",listRuns);g.GET("/model-versions",listModels);g.POST("/model-versions",auth.RequireWrite(),registerModel);g.GET("/online-services",listServices);g.POST("/online-services",auth.RequireWrite(),createService)}
